    public static IEnumerable<object[]> StatusCases()
    {
        foreach (int kind in Enumerable.Range(0,3))
            foreach (int source in Enumerable.Range(0,4))
                foreach (int raw in new[] { -1,0,1,65535,65536,65537,int.MinValue,int.MaxValue })
                    yield return [kind,source,raw];
    }
    [Theory, MemberData(nameof(StatusCases))]
    public void StatusSelectionAndConsumerNarrowingUseActualUserSnapshots(int kind,int source,int raw)
    {
        var f=new UserPhysicalFixture(); int offset=0x17c+kind*4; byte bit=(byte)(4<<kind);
        f.W16(UserPhysicalFixture.Primary,source is 0 or 3?(ushort)1:(ushort)0);
        f.W8(UserPhysicalFixture.Primary+0x1c8,source==0?bit:(byte)0);
        f.W32(UserPhysicalFixture.Primary+(ulong)offset,unchecked((uint)raw));
        f.W16(UserPhysicalFixture.Backup,1); f.W8(UserPhysicalFixture.Backup+0x1c8,bit);
        f.W32(UserPhysicalFixture.Backup+(ulong)offset,unchecked((uint)raw));
        if(source==2) f.W8(UserPhysicalFixture.Backup+0x1c8,0);
        f.W16(UserPhysicalFixture.User+(kind==0?0x14aeul:kind==1?0x14b4ul:0x14b6ul),123);
        U.StatusValue v=U.Status(f.Cursor(),UserPhysicalFixture.User,(U.StatusGetter)kind);
        Assert.Equal(source is 0 or 1?unchecked((ushort)raw):(ushort)123,v.Value);
        Assert.Equal(source is 0 or 1?unchecked((uint)raw):123u,v.ReturnedBits32);
        Assert.Equal(source==0?0:source==1?1:2,v.Selector);
    }
    public static IEnumerable<object[]> CriticalCases()
    {
        foreach(bool reduce in new[] {false,true}) foreach(int source in Enumerable.Range(0,4))
            foreach(int raw in new[] {int.MinValue,-1,0,65537,int.MaxValue}) yield return [reduce,source,raw];
    }
    [Theory, MemberData(nameof(CriticalCases))]
    public void CriticalSnapshotIsSigned32AndOccupiedPrimaryDoesNotFallToBackup(bool reduction,int source,int raw)
    {
        var f=new UserPhysicalFixture(); uint bit=reduction?0x1000u:0x800u; ulong field=reduction?0x1a4ul:0x1a0ul;
        f.W16(UserPhysicalFixture.Primary,source is 0 or 3?(ushort)1:(ushort)0);
        f.W32(UserPhysicalFixture.Primary+0x1c8,source==0?bit:0); f.W32(UserPhysicalFixture.Primary+field,unchecked((uint)raw));
        f.W16(UserPhysicalFixture.Backup,1); f.W32(UserPhysicalFixture.Backup+0x1c8,source==2?0:bit);
        f.W32(UserPhysicalFixture.Backup+field,unchecked((uint)raw));
        f.W16(UserPhysicalFixture.User+(reduction?0x14caul:0x14c6ul),234);
        Assert.Equal(source is 0 or 1?raw:234,U.Critical(f.Cursor(),UserPhysicalFixture.User,reduction));
    }
    [Theory]
    [InlineData(0u)] [InlineData(1u)] [InlineData(2147483647u)] [InlineData(2147483648u)] [InlineData(4294967295u)]
    public void PhysicalDefenseKeepsFullUnsignedDword(uint raw)
    {
        var f=new UserPhysicalFixture(); f.W16(UserPhysicalFixture.Primary,1); f.W8(UserPhysicalFixture.Primary+0x1c8,2);
        f.W32(UserPhysicalFixture.Primary+0x178,raw);
        Assert.Equal(raw,U.Defense(f.Cursor(),UserPhysicalFixture.User));
    }
    public static IEnumerable<object[]> ShieldCases()=>UserPhysicalFixture.Evidence.RootElement.GetProperty("shield_vectors")
        .EnumerateArray().Select(x=>new object[]{x.GetProperty("name").GetString()!});
    [Theory, MemberData(nameof(ShieldCases))]
    public void WholeShieldMatchesFrozenIndependentRationalVectors(string name)
    {
        JsonElement row=UserPhysicalFixture.Evidence.RootElement.GetProperty("shield_vectors").EnumerateArray()
            .Single(x=>x.GetProperty("name").GetString()==name),i=row.GetProperty("inputs"),e=row.GetProperty("expected");
        var f=new UserPhysicalFixture();
        foreach(var pair in new[] {(UserPhysicalFixture.Primary,"primary"),(UserPhysicalFixture.Backup,"backup")})
        {
            f.W16(pair.Item1,(ushort)i.GetProperty(pair.Item2+"_occupied").GetInt32());
            f.W8(pair.Item1+0x1c8,(byte)i.GetProperty(pair.Item2+"_flags").GetInt32());
            f.W32(pair.Item1+0x188,i.GetProperty(pair.Item2+"_ratio").GetUInt32());
            f.W32(pair.Item1+0x18c,i.GetProperty(pair.Item2+"_cap").GetUInt32());
        }
        f.W8(UserPhysicalFixture.User+0x569c,(byte)i.GetProperty("live_present").GetInt32());
        f.W32(UserPhysicalFixture.User+0x56b0,i.GetProperty("live_ratio_bits").GetUInt32());
        f.W32(UserPhysicalFixture.User+0x56ac,i.GetProperty("live_cap_bits").GetUInt32());
        U.Cursor c=f.Cursor(); Assert.Equal(e.GetProperty("eligibility").GetBoolean(),U.ShieldEligible(c,UserPhysicalFixture.User));
        var actual=U.Shield(c,UserPhysicalFixture.User,BitConverter.UInt32BitsToSingle(Convert.ToUInt32(i.GetProperty("damage").GetString(),16)));
        Assert.Equal(e.GetProperty("helper_return").GetInt32()!=0,actual.Applied);
        Assert.Equal(Convert.ToUInt32(e.GetProperty("after_bits").GetString(),16),BitConverter.SingleToUInt32Bits(actual.Damage));
        Assert.Equal(e.GetProperty("selected_ratio").GetString() switch {"primary"=>0,"backup"=>1,_=>2},actual.RatioSelector);
    }
    public static IEnumerable<object[]> MovementCases()
    {
        foreach(uint delta in new uint[] {0,666,667,1331,1332,uint.MaxValue}) foreach(byte flags in Enumerable.Range(0,8).Select(x=>(byte)x))
            yield return [delta,flags];
    }
    [Theory, MemberData(nameof(MovementCases))]
    public void MovementComputesBothUnsignedThresholdsAndWritesOnlyLock(uint delta,byte flags)
    {
        var f=new UserPhysicalFixture(); f.W8(UserPhysicalFixture.User+0x4084,flags); f.W8(UserPhysicalFixture.User+0x408c,(byte)(flags^7));
        f.W32(UserPhysicalFixture.User+0x4088,1000); f.W32(UserPhysicalFixture.User+0x4090,1000);
        var c=f.Cursor(); byte expected=(byte)(((delta<1332?flags:0)|(delta>666?(flags^7):0))&7);
        Assert.Equal(expected,U.Movement(c,UserPhysicalFixture.User,unchecked(1000+delta),"fixture"));
        var writes=c.Steps.Where(x=>x.Kind=="Write").ToArray(); Assert.Equal(2,writes.Length);
        Assert.Equal("01000000",writes[0].After); Assert.Equal("00000000",writes[1].After);
        Assert.All(writes,x=>Assert.Equal(UserPhysicalFixture.User+0x4094,x.Address));
    }
    [Fact]
    public void ContendedMovementDoesNotAcceptAPostLockAnswer()
    {
        var f=new UserPhysicalFixture(); f.W32(UserPhysicalFixture.User+0x4094,1); var c=f.Cursor();
        Assert.Equal("movement.contended_lock",Assert.Throws<U.Domain>(()=>U.Movement(c,UserPhysicalFixture.User,123,"test")).Failure.Operand);
        Assert.Equal("01000000",Assert.Single(c.Steps,x=>x.Kind=="Write").After);
    }
    [Fact]
    public void IdenticalSnapshotPointersStillReadBackupOccupiedAndKeepOneView()
    {
        var f=new UserPhysicalFixture(); f.W64(UserPhysicalFixture.User+0x6e38,UserPhysicalFixture.Primary);
        var c=f.Cursor(); Assert.Equal(0,U.Critical(c,UserPhysicalFixture.User,false));
        Assert.Contains(c.Steps,x=>x.Operand=="critical.backup_occupied"&&x.Address==UserPhysicalFixture.Primary);
    }
    [Fact]
    public void UnknownSkippedBackupAndLiveFieldsRemainUnrequired()
    {
        var f=new UserPhysicalFixture(); f.W16(UserPhysicalFixture.Primary,1); f.W32(UserPhysicalFixture.Primary+0x1c8,0x800);
        f.W32(UserPhysicalFixture.Primary+0x1a0,0xfffffff9); f.Forget(UserPhysicalFixture.User+0x6e38,8); f.Forget(UserPhysicalFixture.User+0x14c6,2);
        Assert.Equal(-7,U.Critical(f.Cursor(),UserPhysicalFixture.User,false));
    }
    [Fact]
    public void UnknownReachedByteFailsAndRawImageIsCopied()
    {
        var f=new UserPhysicalFixture(); var bank=f.Memory(); f.W16(UserPhysicalFixture.Primary,1);
        Assert.Equal(0,new U.Cursor(f.Context,bank,100).U16(UserPhysicalFixture.Primary,0,"old owned snapshot"));
        f.Forget(UserPhysicalFixture.Primary,1);
        Assert.Equal("unknown",Assert.Throws<U.Domain>(()=>U.Status(f.Cursor(),UserPhysicalFixture.User,U.StatusGetter.Dodge)).Failure.Code);
    }
    [Theory]
    [InlineData(200000,0)] [InlineData(299999,99999)] [InlineData(600000,0)] [InlineData(899999,299999)]
    public void ClassLookupReadsSelectedPointerBeforeSignedCountComparison(int id,int index)
    {
        var f=new UserPhysicalFixture(); int bucket=id>=600000?1:0; ulong cell=UserPhysicalFixture.Lookup+(ulong)index*8;
        f.W32(0x14f398f40ul+(ulong)bucket*4,0); f.W64(0x14f398f30ul+(ulong)bucket*8,UserPhysicalFixture.Lookup);
        f.Add(cell,8,"lookup test cell"); f.W64(cell,UserPhysicalFixture.Template);
        var c=f.Cursor(); Assert.Equal(0ul,U.ClassLookup(c,id));
        Assert.Equal(new[]{"class_lookup.count","class_lookup.table","class_lookup.selected_before_count_compare"},c.Steps.Where(x=>x.Kind=="Read").Select(x=>x.Operand));
    }
    [Theory]
    [InlineData(-1)] [InlineData(199999)] [InlineData(300000)] [InlineData(599999)] [InlineData(900000)] [InlineData(int.MaxValue)]
    public void OutOfRangeClassIdReachesNoGlobalOperands(int id)
    {var f=new UserPhysicalFixture();var c=f.Cursor();Assert.Equal(0ul,U.ClassLookup(c,id));Assert.Empty(c.Steps);}
    [Theory]
    [InlineData(0x7f800000u)] [InlineData(0x7fc00000u)] [InlineData(1u)] [InlineData(0x80000001u)]
    public void NonfiniteOrSubnormalShieldOperandsAreTypedUnsupported(uint word)
    {
        var f=new UserPhysicalFixture(); f.W32(UserPhysicalFixture.User+0x56b0,word);
        Assert.Equal("floating",Assert.Throws<U.Domain>(()=>U.Shield(f.Cursor(),UserPhysicalFixture.User,200)).Failure.Code);
    }    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)]
    public void PdefPrimaryBackupLivePrecedenceIsIndependentOfUnsignedValue(int selection)
    {
        var f=new UserPhysicalFixture();f.W16(UserPhysicalFixture.Primary,selection is 0 or 3?(ushort)1:(ushort)0);
        f.W8(UserPhysicalFixture.Primary+0x1c8,selection==0?(byte)2:(byte)0);f.W32(UserPhysicalFixture.Primary+0x178,0x80000001);
        f.W16(UserPhysicalFixture.Backup,1);f.W8(UserPhysicalFixture.Backup+0x1c8,selection==2?(byte)0:(byte)2);f.W32(UserPhysicalFixture.Backup+0x178,0x80000001);
        f.W32(UserPhysicalFixture.User+0x1494,123);Assert.Equal(selection is 0 or 1?0x80000001u:123u,U.Defense(f.Cursor(),UserPhysicalFixture.User));
    }
    [Fact]
    public void NullLookupTableSkipsUnknownSelectedEntryAfterCountAndBase()
    {
        var f=new UserPhysicalFixture();f.W64(0x14f398f30,0);f.Forget(UserPhysicalFixture.Lookup+(212776-200000)*8,8);
        var c=f.Cursor();Assert.Equal(0ul,U.ClassLookup(c,212776));Assert.Equal(2,c.Steps.Count(x=>x.Kind=="Read"));
    }
    [Fact]
    public void SnapshotFallbackCapRejectsAnUnrepresentableSigned64Conversion()
    {
        var f=new UserPhysicalFixture();f.W16(UserPhysicalFixture.Primary,1);f.W8(UserPhysicalFixture.Primary+0x1c8,0x20);
        f.W32(UserPhysicalFixture.Primary+0x188,1);f.W32(UserPhysicalFixture.User+0x56ac,0x5f000000);
        Assert.Equal("conversion",Assert.Throws<U.Domain>(()=>U.Shield(f.Cursor(),UserPhysicalFixture.User,200)).Failure.Code);
    }

