    internal P.SelectedPhysical Selected=RetailNpcPhysicalInstantParametersTests.Select(16556);
    internal ImmutableArray<C.Clock> Clocks;
    internal RetailRandomTransaction Random;
    internal C.Limits Limits=new(128,8_000_000,10000,20,1000,40000);
    internal C.Floating Floating=new(true,true,false,false,true);
    internal C.Infrastructure Infrastructure=new(true,true,true,true);
    internal static JsonDocument Evidence {get;}=Inflate(Corpus,"2a1f1113af63c26cf120941674f7da834e195f2215527dd79125936ce8e0e65a");
    internal static JsonDocument Extra {get;}=Inflate(AdditionalCorpus,"0af3e4214f99126c32b73e7ecd8ddfcf0e6e2d3756233854825a6815f2eee685");
    internal UserPhysicalFixture()
    {
        Add(Npc,0x2000,"source actor","source-life"); Add(User,0x8010,"User actor","user-life");
        Add(Template,0x500,"source template"); Add(Skill,0x1000,"selected current Skill");
        Add(RunInfo,0xa0,"current RunInfo"); Add(Frame,0xe0,"caller frame"); Add(Cache,16,"caller cache");
        Add(Primary,0x1cc,"primary snapshot"); Add(Backup,0x1cc,"backup snapshot");
        foreach(var r in new[]{(0x14275eb74ul,4),(0x14276916cul,4),(0x142769b90ul,4),(0x154827468ul,8),(0x14f523f78ul,4),
            (0x14f398f30ul,16),(0x14f398f40ul,8),(0x145a2c630ul,128),(0x141122d00ul,128),
            (0x141069ed0ul,224),(0x1428b7410ul+240,80),(0x14111ca60ul,480),(0x14111cc40ul,480)}) Add(r.Item1,r.Item2,"global "+r.Item1.ToString("x"));
        W64(Npc,U.NpcVtable); W32(Npc+0x144,2); W32(Npc+0x100,212776); W32(Npc+0x1940,1);
        W32(Npc+0x188c,0); W32(Npc+0x1890,0); W32(Npc+0x1894,0); W64(Npc+0x1850,0); W64(Npc+0x1bf8,0); W64(Npc+0x1848,Template);
        W64(Npc+0x200,0); W64(Npc+0x208,0); W32(Npc+0x914,0); W32(Npc+0x13c,0); W64(Npc+0x1250,0);
        W32(Npc+0x1514,1000); W16(Npc+0x14aa,500); W16(Npc+0x14bc,500); W16(Npc+0x14dc,181); W16(Npc+0x14e0,272);
        W32(Npc+0x8dc,0); W32(Npc+0x14d4,0); W32(Npc+0x8f4,0); W32(Npc+0x120,0x3f800000); W32(Npc+0x124,0);
        W32(Npc+0x1bc8,0); W32(Template+0x23c,0); W32(Template+0x434,0); W8(Template+0x450,0);
        W64(User,U.UserVtable); W32(User+0x144,1); W32(User+0x13c,0); W64(User+0x158,0); W32(User+0x13d0,0);
        W64(User+0x6e50,Primary); W64(User+0x6e38,Backup); W16(Primary,0); W16(Backup,0);
        W16(User+0x14ae,0); W16(User+0x14b4,0); W16(User+0x14b6,1000); W32(User+0x1494,200);
        W16(User+0x14c6,0); W16(User+0x14ca,0); W32(User+0x1514,1000);
