    internal void SelectSkill(P.SelectedPhysical selected)
    {
        Selected=selected; W32(Npc+0x100,(uint)selected.Binding.NpcId);
        ulong selectedCell=Lookup+(ulong)(selected.Binding.NpcId-200000)*8;Add(selectedCell,8,"selected native class pointer "+selected.Binding.NpcId);W64(selectedCell,Template);
        W32(Skill+0x148,(uint)selected.Id); W32(Skill+0x2c8,0); foreach(var word in selected.Constructed)
        {int off=Convert.ToInt32(word.Key,16);if(off==0x47c)W8(Skill+(ulong)off,(byte)word.Value);else W32(Skill+(ulong)off,unchecked((uint)word.Value));}
        Put(Skill+0x480,selected.Condition480.AsSpan()); W8(Skill+0x4d4,0); W8(Skill+0xec4,0); W64(Skill+0xe10,0x140b60ec0);
        W16(RunInfo+0x38,unchecked((ushort)selected.SignedSourceLevel));
    }
    internal C.Clock Clock(C.ClockRole role,ulong caller,ulong tick,uint value)=>new(role,caller,tick,value,User,Context.Operation,Context.Epoch,"user-life","original clock declaration for constructed fixture");
    internal void Add(ulong address,int bytes,string name,string life="fixture allocation")
    {
        if(images.Any(x=>x.Address==address&&x.Raw.Length==bytes)) return;
        images.Add(new(address,Enumerable.Repeat((byte)0xa5,bytes).ToArray(),new byte[bytes],name,life));
    }
    private (Bytes Image,int Offset) Locate(ulong address,int count)
    {var v=images.Single(x=>x.Address<=address&&address+(ulong)count<=x.Address+(ulong)x.Raw.Length);return(v,checked((int)(address-v.Address)));}
    internal void Put(ulong address,ReadOnlySpan<byte> value)
    {var(v,off)=Locate(address,value.Length);value.CopyTo(v.Raw.AsSpan(off));v.Known.AsSpan(off,value.Length).Fill(1);}
    internal void Forget(ulong address,int length){var(v,off)=Locate(address,length);v.Known.AsSpan(off,length).Clear();}
    internal void W8(ulong a,byte v)=>Put(a,[v]);
    internal void W16(ulong a,ushort v){Span<byte>b=stackalloc byte[2];BinaryPrimitives.WriteUInt16LittleEndian(b,v);Put(a,b);}
    internal void W32(ulong a,uint v){Span<byte>b=stackalloc byte[4];BinaryPrimitives.WriteUInt32LittleEndian(b,v);Put(a,b);}
    internal void W64(ulong a,ulong v){Span<byte>b=stackalloc byte[8];BinaryPrimitives.WriteUInt64LittleEndian(b,v);Put(a,b);}
    internal U.Memory Memory()=>U.Memory.Create(images.Select(x=>U.Image.Create(new(x.Address,x.Name,x.Life,Context),x.Raw,x.Known)));
    internal U.Cursor Cursor()=>new(Context,Memory(),10000);
    internal C.Input Input()=>new(Context,Selected,Memory(),new(Npc,User,Template,Skill,RunInfo,Frame,Cache,"source-life","user-life","actual caller ABI constructed"),
        Random,Clocks,Floating,Infrastructure,Limits);
    internal static JsonDocument Inflate(string encoded,string hash)
    {
        using var input=new MemoryStream(Convert.FromBase64String(encoded)); using var zip=new GZipStream(input,CompressionMode.Decompress);using var output=new MemoryStream();zip.CopyTo(output);
        byte[] bytes=output.ToArray();Assert.Equal(hash,U.Hash(bytes));return JsonDocument.Parse(bytes);
    }
    private const string HeadingA="";
    private const string HeadingB="";
    private const string Corpus="";
    private const string AdditionalCorpus="";
}
